-- MCP merged-PR SHA database — exact GitHub evidence snapshot 2026-11-03
-- Canonical source: docs/history/MCP_MAIN_MERGE_SHA_REGISTRY_20261103.json (PR #371)
-- Scope: merged pull requests into Patricked-code/MCP main ONLY (not every git commit).
-- Verification: 186 distinct PRs, 186 unique merge SHA, cross-checked against PR #370 CSV;
-- 8 PR/merge-SHA/date/base spot-checks independently matched GitHub REST PR detail.
-- Import: sqlite3 MCP_MAIN_MERGE_SHA_20261103.sqlite '.read docs/history/MCP_MAIN_MERGE_SHA_DATABASE_20261103.sql'
-- The SQL file is a deterministic source database; no binary SQLite file is versioned.
-- CI/Deploy runs are evidence separate from historical runtime attestations.
-- Helpful queries:
-- SELECT pr_number, merged_at_utc, merge_sha FROM merged_prs ORDER BY merged_at_utc;
-- SELECT * FROM merged_prs WHERE merge_sha = '6576b5287f23566684005adf6032734e2ecdea50';
-- SELECT * FROM merge_evidence_view WHERE pr_number=261;
-- SELECT COUNT(*) FROM merged_prs;
PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS registry_metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS merged_prs (
  pr_number INTEGER PRIMARY KEY CHECK (pr_number>0),
  sequence_number INTEGER NOT NULL UNIQUE CHECK (sequence_number>0),
  merged_at_utc TEXT NOT NULL,
  merge_sha TEXT NOT NULL UNIQUE CHECK (length(merge_sha)=40 AND merge_sha NOT GLOB '*[^0-9a-f]*'),
  base_branch TEXT NOT NULL DEFAULT 'main' CHECK (base_branch='main'),
  title TEXT NOT NULL,
  pr_url TEXT NOT NULL,
  commit_url TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_merged_prs_timestamp ON merged_prs(merged_at_utc);
CREATE TABLE IF NOT EXISTS workflow_evidence (
  pr_number INTEGER NOT NULL REFERENCES merged_prs(pr_number),
  kind TEXT NOT NULL CHECK (kind IN ('CI_MAIN','GOVERNED_DEPLOY_MCP')),
  run_id INTEGER NOT NULL,
  run_url TEXT NOT NULL,
  conclusion TEXT,
  PRIMARY KEY (pr_number,kind)
);
CREATE INDEX IF NOT EXISTS idx_workflow_runs ON workflow_evidence(run_id);
CREATE TABLE IF NOT EXISTS runtime_evidence (
  pr_number INTEGER PRIMARY KEY REFERENCES merged_prs(pr_number),
  evidence_status TEXT NOT NULL,
  runtime_sha TEXT,
  CHECK (runtime_sha IS NULL OR (length(runtime_sha)=40 AND runtime_sha NOT GLOB '*[^0-9a-f]*'))
);
CREATE VIEW IF NOT EXISTS merge_evidence_view AS
SELECT m.pr_number,m.sequence_number,m.merged_at_utc,m.merge_sha,m.title,m.pr_url,m.commit_url,
 ci.run_id AS ci_main_run_id,ci.conclusion AS ci_main_conclusion,
 gd.run_id AS governed_deploy_run_id,gd.conclusion AS governed_deploy_conclusion,
 rt.evidence_status AS runtime_evidence_status,rt.runtime_sha
FROM merged_prs AS m
LEFT JOIN workflow_evidence AS ci ON ci.pr_number=m.pr_number AND ci.kind='CI_MAIN'
LEFT JOIN workflow_evidence AS gd ON gd.pr_number=m.pr_number AND gd.kind='GOVERNED_DEPLOY_MCP'
LEFT JOIN runtime_evidence AS rt ON rt.pr_number=m.pr_number;
COMMIT;
